<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<h1 class="h4 mb-3">Pembayaran</h1>
<?php if ($this->session->flashdata('success')): ?><div class="alert alert-success py-2"><?php echo html_escape($this->session->flashdata('success')); ?></div><?php endif; ?>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Pesanan</th><th>Referensi</th><th>Nominal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?php echo html_escape($payment->order_number); ?></td><td><?php echo html_escape((string)$payment->reference_number); ?></td><td>Rp <?php echo number_format((float)$payment->amount,0,',','.'); ?></td><td><?php echo html_escape($payment->status); ?></td><td><?php if ($payment->status !== 'paid'): ?><form method="post" action="<?php echo site_url('admin/payments/verify/'.$payment->id); ?>" class="d-flex gap-2"><input type="hidden" name="<?php echo $this->security->get_csrf_token_name(); ?>" value="<?php echo $this->security->get_csrf_hash(); ?>"><input class="form-control form-control-sm" name="reference_number" placeholder="Referensi validasi"><button class="btn btn-sm btn-success" type="submit">Verifikasi</button></form><?php else: ?><span class="text-success">Sudah terverifikasi</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
